fn main() -> Int {
  let original = Vec[Int].new();
  original.push(1);

  let moved = original;       // 1. Ownership: original is gone
  let copy = moved.clone();   // 2. Clone: independent copy
  let ref = &moved;           // 3. Borrow: shared read access

  io.println(ref.len());
  return copy.len() as Int;
}
